import ballerina/io;

function areAbcCountsEqual(string str, boolean checkCase) returns boolean {
    int a = 0;
    int b = 0;
    int c = 0;
    string s = str;
    if checkCase { s = s.toLowerAscii(); }
    foreach string:Char ch in s {
        if ch == "a" {
            a += 1;
        } else if ch == "b" {
            b += 1;
        } else if ch == "c" {
            c += 1;
        }
    }
    return a == b && b == c;
}

function occurs(string s, string find) returns int {
    return re `${find}`.split(s).length() - 1;
}

public function main() returns error? {
    while true {
        string s = io:readln("Enter a string or 'q' to quit: ");
        if s == "q" { break; }
        string res = areAbcCountsEqual(s, true) ? "equal" : "not equal";
        io:println("The counts of 'a', 'b', 'c' are ", res, ".\n");
    }

    var words = check io:fileReadLines("unixdict.txt");  // local copy
    var ct = words.filter(w => w.includes("a") && areAbcCountsEqual(w, false)).length();
    io:println("\nThere are ", ct, " words in unixdict.txt which have at least one 'a' and equal numbers of 'a', 'b' and 'c'.");

    words = check io:fileReadLines("words_alpha.txt");  // local copy
    var eligible = from string w in words
                   let int a = occurs(w, "a")
                   where a >= 2
                   let int b = occurs(w, "b")
                   where a == b
                   let int c = occurs(w, "c")
                   where b == c
                   select w;
    io:println("\nWords in words_alpha.txt which contain equal numbers of 'a', 'b' and 'c' and at least two of each of them (", eligible.length(), " such words found):");
    io:println(string:'join("\n", ...eligible));
}

import ballerina/io;

function occurs(string s, string find) returns int {
    return re `${find}`.split(s).length() - 1;
}

function abcIncrementalCounts(string fileName, string[] letters, int minCount)
    returns string[]|error {
    string[] res = [];
    var words = check io:fileReadLines(fileName); // local copy
    foreach string w in words {
        string word = w.toLowerAscii();
        int c1 = occurs(word, letters[0]);
        if  c1 < minCount { continue; }
        int c2 = occurs(word, letters[1]);
        if  c2 < minCount { continue; }
        int c3 = occurs(word, letters[2]);
        if  c3 < minCount { continue; }
        int[] l = (<int[]>[c1, c2, c3]).sort();
        if l[1] != l[0] + 1 || l[2] != l[1] + 1 { continue; }
        res.push(word);
    }
    return res;
}

public function main() returns error? {
    string[] fileNames = ["unixdict.txt", "words_alpha.txt"];
    string[][] letters = [["a", "b", "c"], ["t", "h", "e"], ["c", "i", "o"]];
    int[][] minCounts  = [[1, 1, 2], [2, 2, 3]];
    foreach int i in 0..<fileNames.length() {
        io:println("Using ", fileNames[i], ":\n");
        foreach int j in 0..<letters.length() {
            io:println("Letters: ", letters[j], " -- Minimum count ", minCounts[i][j]);
            var res = check abcIncrementalCounts(fileNames[i], letters[j], minCounts[i][j]);
            if res.length() > 0 {
                io:println(string:'join("\n", ...res));
            } else {
                io:println("<none>");
            }
            io:println();
        }
        io:println();
    }
}

import ballerina/io;

function r(string word, string[] bl) returns boolean {
    if word == "" { return true; }
    int c = word[0].toBytes()[0] | 32;
   foreach int i in 0..<bl.length() {
        var b = bl[i];
        if c == (b.toBytes()[0] | 32) || c == (b.toBytes()[1] | 32) {
            bl[i] = bl[0];
            bl[0] = b;
            if r(word.substring(1), bl.slice(1)) { return true; }
            var t = bl[i];
            bl[i] = bl[0];
            bl[0] = t;
        }
   }
   return false;
}

