    }

    private static void rotate(int[] ix) {
        int last = n[ix[3]];
        for (int i = 3; i >= 1; i--) {
            n[ix[i]] = n[ix[i - 1]];
        }
        n[ix[0]] = last;
    }

    private static boolean hasWon() {
        for (int i = 0; i < 16; i++) {
            if (n[i] != i + 1) {
                return false;
            }
        }
        return true;
    }
